package com.wanderly.model;
import jakarta.persistence.*; import jakarta.validation.constraints.*; import java.time.LocalDate;
@Entity public class Trip { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=90) private String title; @NotBlank @Size(max=90) private String destination; @NotNull private LocalDate startDate; @NotNull private LocalDate endDate; @Min(1) @Max(30) private int travellers=2; @Enumerated(EnumType.STRING) private TripStatus status=TripStatus.PLANNED; @Size(max=600) private String notes; private String imageUrl; public Trip(){} public Long getId(){return id;} public void setId(Long v){id=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDestination(){return destination;} public void setDestination(String v){destination=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public int getTravellers(){return travellers;} public void setTravellers(int v){travellers=v;} public TripStatus getStatus(){return status;} public void setStatus(TripStatus v){status=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String v){imageUrl=v;} }
